/// `uo_docx::session::ops::revision_cmds::MarkupOptions`
#[derive(Debug, Clone, PartialEq)]
pub struct MarkupOptions {
    pub ins_del: bool,
    pub formatting: bool,
    pub comments: bool,
    pub balloons: Balloons,
    pub authors: Option<Vec<Vec<u16>>>,
}

impl MarkupOptions {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 16;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.ins_del, self.formatting, self.comments, self.authors.is_some()]);
        self.balloons.encode(w);
        if let Some(v) = &self.authors {
            w.len(v.len());
            for e0 in v.iter() {
                w.utf16(e0);
            }
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(4)?;
        let f_ins_del = bit(bm, 0);
        let f_formatting = bit(bm, 1);
        let f_comments = bit(bm, 2);
        let f_balloons = Balloons::decode(r)?;
        let f_authors = if bit(bm, 3) { Some({ let n = r.list_of::<Vec<u16>>(8)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(r.utf16()?); } v }) } else { None };
        Ok(Self { ins_del: f_ins_del, formatting: f_formatting, comments: f_comments, balloons: f_balloons, authors: f_authors })
    }
}

