/// What a decoder has received so far in one generation: the entries of every table (ids are positions).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Tables {
    /// The generation the entries belong to (`None` before the first message).
    pub generation: Option<u32>,
}

impl Tables {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn clear(&mut self) {
        *self = Self::default();
    }

    /// The number of entries of every table, in declaration order.
    pub fn lens(&self) -> [usize; 0] {
        []
    }

    /// Drops the entries past `lens` (a failed message leaves the tables as they were).
    pub fn truncate(&mut self, lens: &[usize; 0]) {
        let [] = *lens;
    }

    /// The entries past `lens` as the delta that would carry them (the generation is the tables').
    pub fn delta_since(&self, lens: &[usize; 0]) -> Delta {
        let [] = *lens;
        Delta {
            generation: self.generation.unwrap_or(0),
        }
    }
}

/// The new entries a message carries, per table, and its generation (the encoder's input).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Delta {
    pub generation: u32,
}

/// The id and generation of a message, after the magic and the schema hash were checked.
pub fn peek_header(buf: &[u8]) -> Result<uo_codec::Header, DecodeError> {
    Reader::new(buf, &Limits::default()).header(&MAGIC, &SCHEMA_HASH)
}

/// Writes a `Exec` message: the header, the new table entries of `delta`, the body.
/// On an error `out` is left as it was.
pub fn encode_exec(out: &mut Vec<u8>, delta: &Delta, msg: &Exec) -> Result<(), EncodeError> {
    let mut w = Writer::new(out);
    w.header(&MAGIC, &SCHEMA_HASH, MSG_EXEC, delta.generation);
    msg.encode(&mut w);
    w.finish()
}

/// Reads a `Exec` message. `tables` is the state of this stream of messages: the new entries are
/// appended, a new generation replaces them, and an error leaves them as they were.
pub fn decode_exec(buf: &[u8], tables: &mut Tables, limits: &Limits) -> Result<Exec, DecodeError> {
    let mut r = Reader::new(buf, limits);
    let head = r.header(&MAGIC, &SCHEMA_HASH)?;
    if head.message != MSG_EXEC {
        return Err(DecodeError::WrongMessage { expected: MSG_EXEC, found: head.message });
    }
    let previous = if tables.generation == Some(head.generation) { None } else { Some(std::mem::take(tables)) };
    let lens = tables.lens();
    match decode_exec_body(&mut r, tables) {
        Ok(msg) => {
            tables.generation = Some(head.generation);
            Ok(msg)
        }
        Err(e) => {
            match previous { Some(p) => *tables = p, None => tables.truncate(&lens) }
            Err(e)
        }
    }
}

fn decode_exec_body(r: &mut Reader<'_>, _tables: &mut Tables) -> Result<Exec, DecodeError> {
    let msg = Exec::decode(r)?;
    r.end()?;
    Ok(msg)
}

